% Denoise Signal using the Discrete Wavelet Transform (DWT)

% Generated by MATLAB(R) 9.10 and Wavelet Toolbox 5.6.
% Generated on: 20-8월-2021 04:14:31
denoise_test(:,501)= FordBTEST_double(:,1);
for i = 2:501
    test = FordBTEST_double(:,i)
denoise_test(:,i-1) = wdenoise(test,3, ...
    'Wavelet', 'db14', ...
    'DenoisingMethod', 'UniversalThreshold', ...
    'ThresholdRule', 'Hard', ...
    'NoiseEstimate', 'LevelIndependent');
end
denoise_train(:,501)= FordBTRAIN_double(:,1);
for i = 2:501
    normal = FordBTEST_double(:,i);
denoise_train(:,i-1) = wdenoise(normal,3, ...
    'Wavelet', 'db14', ...
    'DenoisingMethod', 'UniversalThreshold', ...
    'ThresholdRule', 'Hard', ...
    'NoiseEstimate', 'LevelIndependent');
end

plot(FordBTEST_double(:,2));
hold on
plot(denoise_test(:,1));

for i = 2:501
sound(FordBTRAIN_double(:,i),2000)
pause(1)
sound(denoise_test(:,i),2000)
end
cleanAudio = FordBTRAIN_double(:,2);
noise = FordBTRAIN_double(:,2);
ind = randi(numel(noise) - numel(cleanAudio) + 1, 1, 1);
noiseSegment = noise(ind:ind + numel(cleanAudio) - 1);

speechPower = sum(cleanAudio.^2);
noisePower = sum(noiseSegment.^2);
noisyAudio = cleanAudio + sqrt(speechPower/noisePower) * noiseSegment;

sound(noisyAudio,1000)
sound(cleanAudio,1000)
fs=2000
t = (1/fs) * (0:numel(cleanAudio)-1);

subplot(2,1,1)
plot(t,cleanAudio)
title("Clean Audio")
grid on

subplot(2,1,2)
plot(t,noisyAudio)
title("Noisy Audio")
xlabel("Time (s)")
grid on
